from fnmatch import fnmatchcase

def matches(statement, request):
    """True if the statement applies to the request (no conditions in this exercise)."""
    return (any(fnmatchcase(request["principal"], p) for p in statement["principals"])
            and any(fnmatchcase(request["action"], a) for a in statement["actions"])
            and any(fnmatchcase(request["resource"], r) for r in statement["resources"]))

def evaluate(policies, request):
    """Return "ALLOW" or "DENY". This version lets the first matching statement decide."""
    for statement in policies:
        if matches(statement, request):
            return statement["effect"].upper()
    return "DENY"

