def exposed_admin_rules(rules):
    """Names (sorted) of firewall rules that let the whole internet reach SSH (22) or RDP (3389).
    Each rule: {"name": ..., "source": "0.0.0.0/0" or another network, "from_port": int, "to_port": int}."""
    return sorted(r["name"] for r in rules if r["source"] == "0.0.0.0/0" and r["from_port"] == 22)

exercises.reference:
import ipaddress

ADMIN_PORTS = (22, 3389)

def exposed_admin_rules(rules):
    exposed = []
    for r in rules:
        whole_internet = ipaddress.ip_network(r["source"]).prefixlen == 0   # 0.0.0.0/0 or ::/0
        covers_admin = any(r["from_port"] <= p <= r["to_port"] for p in ADMIN_PORTS)
        if whole_internet and covers_admin:
            exposed.append(r["name"])
    return sorted(exposed)
